mapper.select:
SELECT * FROM tb_user_sign_statistics 
WHERE user_id = #{userId}
LIMIT 1

mapper.update:
UPDATE tb_user_sign_statistics 
SET continuous_days = #{continuousDays}, update_time = NOW()
WHERE user_id = #{userId}

UPDATE tb_user_sign_statistics 
SET max_continuous_days = #{maxContinuousDays}, update_time = NOW()
WHERE user_id = #{userId} AND max_continuous_days < #{maxContinuousDays}
